// GraphHasSuffix applies the HasSuffix predicate on the "graph" field.
func GraphHasSuffix(v string) predicate.AiAgentApp {
	return predicate.AiAgentApp(sql.FieldHasSuffix(FieldGraph, v))
}

// GraphIsNil applies the IsNil predicate on the "graph" field.
func GraphIsNil() predicate.AiAgentApp {
	return predicate.AiAgentApp(sql.FieldIsNull(FieldGraph))
}

// GraphNotNil applies the NotNil predicate on the "graph" field.
func GraphNotNil() predicate.AiAgentApp {
	return predicate.AiAgentApp(sql.FieldNotNull(FieldGraph))
}

// GraphEqualFold applies the EqualFold predicate on the "graph" field.
func GraphEqualFold(v string) predicate.AiAgentApp {
	return predicate.AiAgentApp(sql.FieldEqualFold(FieldGraph, v))
}

// GraphContainsFold applies the ContainsFold predicate on the "graph" field.
func GraphContainsFold(v string) predicate.AiAgentApp {
	return predicate.AiAgentApp(sql.FieldContainsFold(FieldGraph, v))
}

// EnabledEQ applies the EQ predicate on the "enabled" field.
func EnabledEQ(v bool) predicate.AiAgentApp {
	return predicate.AiAgentApp(sql.FieldEQ(FieldEnabled, v))
}

// EnabledNEQ applies the NEQ predicate on the "enabled" field.
func EnabledNEQ(v bool) predicate.AiAgentApp {
	return predicate.AiAgentApp(sql.FieldNEQ(FieldEnabled, v))
}

// HasRevisions applies the HasEdge predicate on the "revisions" edge.
func HasRevisions() predicate.AiAgentApp {
	return predicate.AiAgentApp(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, RevisionsTable, RevisionsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasRevisionsWith applies the HasEdge predicate on the "revisions" edge with a given conditions (other predicates).
func HasRevisionsWith(preds ...predicate.AiAgentRevision) predicate.AiAgentApp {
	return predicate.AiAgentApp(func(s *sql.Selector) {
		step := newRevisionsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.AiAgentApp) predicate.AiAgentApp {
	return predicate.AiAgentApp(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.AiAgentApp) predicate.AiAgentApp {
	return predicate.AiAgentApp(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.AiAgentApp) predicate.AiAgentApp {
	return predicate.AiAgentApp(sql.NotPredicates(p))
}
